//! Safe wrappers around the UXP Hybrid SDK's C API. Everything `unsafe` about UXP lives here.

#![allow(
    non_camel_case_types,
    non_upper_case_globals,
    non_snake_case,
    dead_code
)]

use std::ffi::CStr;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::ptr::null_mut;
use std::sync::OnceLock;

/// The SDK's types and function table, generated by build.rs from Adobe's headers
pub mod sdk {
    include!(concat!(env!("OUT_DIR"), "/sdk.rs"));
}
pub use sdk::{addon_apis, addon_callback_info, addon_env, addon_status, addon_value};

/// The function table UXP hands to uxp_addon_init, kept for every later call
static APIS: OnceLock<addon_apis> = OnceLock::new();

pub fn set_apis(apis: addon_apis) {
    let _ = APIS.set(apis);
}

fn apis() -> &'static addon_apis {
    APIS.get()
        .expect("uxp_addon_init stores the API table before anything else runs")
}

/// Calls one entry of the table, e.g. `call!(uxp_addon_get_null(env, &mut out))`,
/// and turns a status other than addon_ok into an Err naming the function
macro_rules! call {
    ($name:ident($($arg:expr),* $(,)?)) => {{
        let f = apis().$name.ok_or(concat!(stringify!($name), " is missing"))?;
        match unsafe { f($($arg),*) } {
            addon_status::addon_ok => Ok::<(), String>(()),
            status => Err(format!("{} failed: {:?}", stringify!($name), status)),
        }
    }};
}

pub type JsResult = Result<addon_value, String>;

/// The JavaScript arguments of a call; fewer than `N` leaves the rest null
pub fn args<const N: usize>(
    env: addon_env,
    info: addon_callback_info,
) -> Result<([addon_value; N], usize), String> {
    let mut argv = [null_mut(); N];
    let mut argc = N;
    call!(uxp_addon_get_cb_info(
        env,
        info,
        &mut argc,
        argv.as_mut_ptr(),
        null_mut(),
        null_mut()
    ))?;
    Ok((argv, argc.min(N)))
}

pub fn to_string(env: addon_env, value: addon_value, name: &str) -> Result<String, String> {
    let mut len = 0usize;
    call!(uxp_addon_get_value_string_utf8(
        env,
        value,
        null_mut(),
        0,
        &mut len
    ))
    .map_err(|_| format!("{name} must be a string"))?;
    let mut buf = vec![0u8; len + 1];
    call!(uxp_addon_get_value_string_utf8(
        env,
        value,
        buf.as_mut_ptr().cast(),
        buf.len(),
        &mut len
    ))?;
    buf.truncate(len);
    String::from_utf8(buf).map_err(|_| format!("{name} is not valid UTF-8"))
}

pub fn to_i32(env: addon_env, value: addon_value, name: &str) -> Result<i32, String> {
    let mut out = 0i32;
    call!(uxp_addon_get_value_int32(env, value, &mut out))
        .map_err(|_| format!("{name} must be a number"))?;
    Ok(out)
}

pub fn to_bool(env: addon_env, value: addon_value) -> bool {
    let mut out = false;
    let _ = (|| call!(uxp_addon_get_value_bool(env, value, &mut out)))();
    out
}

pub fn to_strings(env: addon_env, value: addon_value, name: &str) -> Result<Vec<String>, String> {
    let mut is_array = false;
    call!(uxp_addon_is_array(env, value, &mut is_array))?;
    if !is_array {
        return Err(format!("{name} must be an array of strings"));
    }
    let mut len = 0u32;
    call!(uxp_addon_get_array_length(env, value, &mut len))?;
    (0..len)
        .map(|i| {
            let mut item = null_mut();
            call!(uxp_addon_get_element(env, value, i, &mut item))?;
            to_string(env, item, &format!("{name}[{i}]"))
        })
        .collect()
}

pub fn from_str(env: addon_env, s: &str) -> JsResult {
    let mut out = null_mut();
    call!(uxp_addon_create_string_utf8(
        env,
        s.as_ptr().cast(),
        s.len(),
        &mut out
    ))?;
    Ok(out)
}

pub fn from_i32(env: addon_env, n: i32) -> JsResult {
    let mut out = null_mut();
    call!(uxp_addon_create_int32(env, n, &mut out))?;
    Ok(out)
}

pub fn from_bool(env: addon_env, b: bool) -> JsResult {
    let mut out = null_mut();
    call!(uxp_addon_get_boolean(env, b, &mut out))?;
    Ok(out)
}

pub fn null(env: addon_env) -> JsResult {
    let mut out = null_mut();
    call!(uxp_addon_get_null(env, &mut out))?;
    Ok(out)
}

pub fn undefined(env: addon_env) -> JsResult {
    let mut out = null_mut();
    call!(uxp_addon_get_undefined(env, &mut out))?;
    Ok(out)
}

pub fn from_opt_i32(env: addon_env, n: Option<i32>) -> JsResult {
    n.map_or_else(|| null(env), |n| from_i32(env, n))
}

/// A plain object from (name, value) pairs
pub fn object(env: addon_env, props: &[(&CStr, addon_value)]) -> JsResult {
    let mut out = null_mut();
    call!(uxp_addon_create_object(env, &mut out))?;
    for (name, value) in props {
        call!(uxp_addon_set_named_property(
            env,
            out,
            name.as_ptr(),
            *value
        ))?;
    }
    Ok(out)
}

/// The signature UXP calls: what `export` takes
pub type Callback = unsafe extern "C" fn(addon_env, addon_callback_info) -> addon_value;

/// Puts a native function on `exports` under `name`
pub fn export(
    env: addon_env,
    exports: addon_value,
    name: &CStr,
    callback: Callback,
) -> Result<(), String> {
    let mut f = null_mut();
    call!(uxp_addon_create_function(
        env,
        name.as_ptr(),
        name.to_bytes().len(),
        Some(callback),
        null_mut(),
        &mut f
    ))?;
    call!(uxp_addon_set_named_property(env, exports, name.as_ptr(), f))?;
    Ok(())
}

/// Runs the body of an exported function. An Err or a panic becomes a JavaScript exception:
/// neither may reach UXP as they are, a panic unwinding into Premiere would crash it.
pub fn guarded(env: addon_env, body: impl FnOnce() -> JsResult) -> addon_value {
    let message = match catch_unwind(AssertUnwindSafe(body)) {
        Ok(Ok(value)) => return value,
        Ok(Err(message)) => message,
        Err(_) => "Internal error in the PostPin addon".to_string(),
    };
    if let Some(throw) = APIS.get().and_then(|a| a.uxp_addon_throw_error) {
        // the message may contain NUL bytes in theory; then it is cut there
        let msg = std::ffi::CString::new(message.replace('\0', " ")).unwrap_or_default();
        unsafe { throw(env, std::ptr::null(), msg.as_ptr()) };
    }
    null_mut()
}
